statement:
Call an array `nums` **beautiful** when all of these hold:

- it has exactly `n` elements;
- every element is a positive integer and no value appears twice;
- no two elements at different positions add up to exactly `target`.

Given the positive integers `n` and `target`, return the smallest total that a beautiful array can have, taken modulo `10^9 + 7`.

validator:
function validate([n, target]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is a whole number from 1 to 10^9.';
  if (!Number.isInteger(target) || target < 1 || target > 1000000000) return 'target is a whole number from 1 to 10^9.';
  return null;
}

reference:
function minimumPossibleSum(n, target) {
  const MOD = 1000000007n;
  const half = Math.floor(target / 2);
  const low = BigInt(Math.min(n, half));
  const high = BigInt(n) - low;
  const lowSum = (low * (low + 1n)) / 2n;
  const start = BigInt(target);
  const highSum = (high * (start + start + high - 1n)) / 2n;
  return Number((lowSum + highSum) % MOD);
}

brute:
function minimumPossibleSum(n, target) {
  // Greedy simulation: take the smallest number whose partner is not already taken.
  const chosen = new Set();
  let total = 0;
  for (let x = 1; chosen.size < n; x++) {
    if (chosen.has(target - x)) continue;
    chosen.add(x);
    total = (total + x) % 1000000007;
  }
  return total;
}

