function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 12);
    const target = 1 + Math.floor(rand() * 25);
    return [n, target];
  }
  const big = () => 1 + Math.floor(rand() * 1000000000);
  const mode = rand();
  if (mode < 0.25) return [big(), 1 + Math.floor(rand() * 1000)];
  if (mode < 0.5) return [1 + Math.floor(rand() * 100000), big()];
  if (mode < 0.75) return [1000000000 - Math.floor(rand() * 1000), 1000000000 - Math.floor(rand() * 1000)];
  return [big(), big()];
}
